export const projectManagementTextbookHtml = "\n  <div class=\"tkd-page-scope font-sans antialiased bg-[#FAF8F6] text-[#333333]\">\n\n    <!-- COVER HEADER CHO BẢN IN HOẶC XUẤT PDF A4 -->\n    <div class=\"print-document-header hidden print:block text-center border-b-2 border-[#8B1E2D] pb-4 mb-6\">\n      <div class=\"text-[12pt] font-semibold text-[#8B1E2D] tracking-wider uppercase\">TRƯỜNG CAO ĐẲNG KINH TẾ TP. HỒ CHÍ MINH — KHOA QUẢN TRỊ KINH DOANH</div>\n      <h1 class=\"text-[20pt] font-extrabold text-[#111827] uppercase tracking-tight mt-2 mb-1\">\n        GIÁO TRÌNH QUẢN TRỊ DỰ ÁN (MH38)\n      </h1>\n      <div class=\"text-[11pt] text-[#4B5563] italic\">\n        Tài liệu học tập chính quy bậc Cao đẳng &amp; Đại học — Chủ biên: ThS. NGUYỄN THỊ TRÚC PHƯƠNG\n      </div>\n      <div class=\"text-[10pt] text-[#6B7280] mt-2 flex justify-between items-center border-t border-[#E5E7EB] pt-1\">\n        <span>Mã học phần: MH38 (3 tín chỉ / 45 tiết)</span>\n        <span class=\"print-timestamp\">Năm học: <span class=\"js-current-year\"></span></span>\n        <span>Cổng học liệu số: NGUYỄN THỊ TRÚC PHƯƠNG</span>\n      </div>\n    </div>\n\n    <!-- HEADER BANNER ONLINE LUXURY RED TONE -->\n    <header class=\"no-print w-full bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#C62828] text-white py-8 sm:py-10 px-4 shadow-md border-b border-[#FCEEEF]/20\">\n      <div class=\"max-w-5xl mx-auto text-center space-y-2\">\n        <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/15 backdrop-blur-sm border border-white/25 text-xs font-semibold tracking-wider uppercase text-[#FCEEEF]\">\n          <span>📘</span> Giáo Trình Học Phần Trọng Tâm — Bậc Cao Đẳng &amp; Đại Học\n        </div>\n        <h1 class=\"text-xl sm:text-2xl md:text-3xl lg:text-4xl font-extrabold tracking-tight uppercase leading-tight text-white drop-shadow-xs m-0\">\n          GIÁO TRÌNH QUẢN TRỊ DỰ ÁN\n        </h1>\n        <p class=\"text-xs sm:text-sm text-[#FCEEEF]/90 max-w-3xl mx-auto font-medium leading-relaxed\">\n          Chủ biên: <strong>ThS. Nguyễn Thị Trúc Phương</strong> — Khoa Quản trị Kinh doanh, Trường Cao đẳng Kinh tế TP.HCM (HCE). Hệ thống kiến thức chuẩn hóa 8 chương rút gọn còn 50% tinh hoa học thuật, giữ trọn vẹn toàn bộ công thức, mô hình và bảng biểu chuyên môn.\n        </p>\n      </div>\n    </header>\n\n    <!-- THANH ĐIỀU HƯỚNG NHANH & HÀNH ĐỘNG HỌC LIỆU -->\n    <div class=\"no-print bg-white border-b border-[#E8E0E1] sticky top-0 z-30 shadow-2xs\">\n      <div class=\"max-w-5xl mx-auto px-3.5 sm:px-6 py-2.5 flex flex-wrap items-center justify-between gap-2 text-xs\">\n        <div class=\"flex items-center gap-2\">\n          <a href=\"/study-corner\" class=\"inline-flex items-center gap-1.5 font-bold text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3 py-1.5 rounded-lg transition-colors\">\n            <span>←</span> Về Góc Học Tập\n          </a>\n          <a href=\"/study-corner/project-management/intro\" class=\"inline-flex items-center gap-1.5 font-bold text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3 py-1.5 rounded-lg transition-colors\">\n            <span>📋</span> Giới Thiệu &amp; Đề Cương\n          </a>\n        </div>\n        <div class=\"flex items-center gap-2\">\n          <button type=\"button\" onclick=\"window.print()\" class=\"inline-flex items-center gap-1.5 font-bold text-[#8B1E2D] hover:bg-[#FCEEEF] border border-[#8B1E2D]/40 px-3 py-1.5 rounded-lg transition-all cursor-pointer\">\n            <span>🖨️</span> In Giáo Trình\n          </button>\n          <button type=\"button\" onclick=\"window.print()\" class=\"inline-flex items-center gap-1.5 font-bold text-white bg-[#8B1E2D] hover:bg-[#C62828] px-3 py-1.5 rounded-lg transition-all shadow-2xs cursor-pointer\">\n            <span>📄</span> Xuất PDF A4\n          </button>\n        </div>\n      </div>\n    </div>\n\n    <!-- KHUNG THÔNG TIN HỌC PHẦN TỔNG QUAN -->\n    <div class=\"max-w-5xl mx-auto px-3.5 sm:px-6 pt-6\">\n      <div class=\"bg-white rounded-2xl border border-[#E8E0E1] p-4 sm:p-6 shadow-2xs grid grid-cols-2 sm:grid-cols-4 gap-4 text-center\">\n        <div class=\"border-r border-[#E8E0E1] last:border-r-0\">\n          <span class=\"block text-2xs font-bold text-slate-500 uppercase tracking-wider\">Mã Học Phần</span>\n          <span class=\"text-sm sm:text-base font-extrabold text-[#8B1E2D]\">MH38</span>\n        </div>\n        <div class=\"border-r border-[#E8E0E1] last:border-r-0\">\n          <span class=\"block text-2xs font-bold text-slate-500 uppercase tracking-wider\">Khối Lượng</span>\n          <span class=\"text-sm sm:text-base font-extrabold text-slate-900\">3 Tín Chỉ (45 Tiết)</span>\n        </div>\n        <div class=\"border-r border-[#E8E0E1] last:border-r-0\">\n          <span class=\"block text-2xs font-bold text-slate-500 uppercase tracking-wider\">Chủ Biên</span>\n          <span class=\"text-sm sm:text-base font-extrabold text-[#8B1E2D]\">ThS. Nguyễn Thị Trúc Phương</span>\n        </div>\n        <div>\n          <span class=\"block text-2xs font-bold text-slate-500 uppercase tracking-wider\">Đơn Vị Quản Lý</span>\n          <span class=\"text-sm sm:text-base font-extrabold text-slate-900\">Khoa QTKD — HCE</span>\n        </div>\n      </div>\n    </div>\n\n    <!-- THÂN TRANG CHẠY DÀI TỰ NHIÊN (MAX-W-5XL) -->\n    <div class=\"max-w-5xl mx-auto px-3.5 sm:px-6 py-6 space-y-8\">\n\n      <!-- MỤC LỤC TỔNG THỂ GIÁO TRÌNH (INTERACTIVE DIRECT NAVIGATION) -->\n      <nav aria-label=\"Mục lục giáo trình\" class=\"no-print rounded-3xl bg-white border border-[#E8E0E1] p-5 sm:p-8 shadow-sm\">\n        <div class=\"flex items-center justify-between gap-2 mb-4\">\n          <div class=\"flex items-center gap-2\">\n            <span class=\"px-3 py-1 rounded-full bg-[#FCEEEF] text-[#8B1E2D] text-xs font-bold tracking-wider uppercase\">Cấu Trúc Giáo Trình Chuẩn Hóa</span>\n          </div>\n          <span class=\"text-xs font-semibold text-slate-500\">8 Chương Hoàn Chỉnh</span>\n        </div>\n        <h2 class=\"text-xl sm:text-2xl font-extrabold text-[#111827] tracking-tight mb-4\">\n          MỤC LỤC TỔNG THỂ GIÁO TRÌNH QUẢN TRỊ DỰ ÁN\n        </h2>\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-3\">\n          <a href=\"#chuong1\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">01</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Tổng quan về quản trị dự án</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Khái niệm đầu tư, chu kỳ dự án, các yếu tố ảnh hưởng dòng tiền.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong2\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">02</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Lựa chọn dự án</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Tiêu chí định lượng PP, NPV, IRR, PI và tiêu chí định tính.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong3\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">03</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Tổ chức dự án</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">3 mô hình tổ chức (Chức năng, Dự án, Ma trận) và lãnh đạo nhóm.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong4\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">04</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Lập kế hoạch &amp; ngân sách</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Cấu trúc phân rã công việc WBS và ước tính chi phí dự án.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong5\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">05</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Lập tiến độ dự án</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Biểu đồ Gantt, sơ đồ mạng AOA/AON, phương pháp CPM và PERT.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong6\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">06</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Phân bổ nguồn lực</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Quy tắc phân bổ, san bằng tài nguyên và tối ưu hóa thời gian - chi phí.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong7\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">07</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Kiểm soát dự án</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Quy trình kiểm soát và phương pháp quản trị giá trị thu được (EVM).</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong8\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">08</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Đánh giá &amp; kết thúc</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Quy trình nghiệm thu, 4 hình thức kết thúc và báo cáo tổng kết dự án.</p>\n              </div>\n            </div>\n          </a>\n        </div>\n      </nav>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 1: TỔNG QUAN VỀ QUẢN TRỊ DỰ ÁN                                     -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong1\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] overflow-hidden text-[#333333] transition-all\">\n        <div class=\"p-4 sm:p-7 space-y-6\">\n\n          <!-- Chapter Header Banner -->\n          <div class=\"chapter-header-banner rounded-2xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] p-5 sm:p-7 text-white shadow-md relative overflow-hidden\">\n            <div class=\"relative z-10 flex flex-col gap-2\">\n              <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-400 text-slate-950 font-black text-xs uppercase tracking-wider w-fit\">\n                <span>CHƯƠNG 01</span>\n              </div>\n              <h2 class=\"text-xl sm:text-2xl md:text-3xl font-black tracking-tight uppercase leading-tight text-white m-0\">\n                Tổng Quan Về Quản Trị Dự Án\n              </h2>\n              <p class=\"text-xs sm:text-sm leading-relaxed max-w-3xl m-0 font-medium text-[#FCEEEF]\">\n                Bản chất của hoạt động đầu tư, các hình thức đầu tư theo Luật Đầu tư, đặc điểm cốt lõi của dự án, chu kỳ sống dự án, các nhân tố ảnh hưởng dòng ngân lưu và khung quy trình quản trị dự án hiện đại.\n              </p>\n            </div>\n          </div>\n\n          <!-- Chapter Objectives Card -->\n          <div class=\"bg-gradient-to-br from-white via-[#FCEEEF]/40 to-[#FAF8F6] rounded-2xl border border-[#E8E0E1] p-4 sm:p-5 shadow-2xs\">\n            <div class=\"flex items-center gap-2.5 mb-3 border-b border-[#E8E0E1] pb-2.5\">\n              <span class=\"w-7 h-7 rounded-lg bg-[#8B1E2D] text-white flex items-center justify-center text-sm font-bold\">🎯</span>\n              <div>\n                <h3 class=\"font-extrabold text-[#111827] text-xs sm:text-sm m-0 tracking-tight\">Mục Tiêu Trọng Tâm Chương 1</h3>\n                <p class=\"text-[11px] text-[#666666] m-0\">Chuẩn đầu ra kiến thức và năng lực sinh viên sau khi hoàn thành chương:</p>\n              </div>\n            </div>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs\">\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] flex items-start gap-2.5\">\n                <span class=\"w-5 h-5 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                <div>\n                  <strong class=\"text-[#111827]\">Khái niệm &amp; Hình thức đầu tư:</strong>\n                  <p class=\"text-[#666666] m-0 mt-0.5\">Phân tích được khái niệm đầu tư, các mục tiêu đầu tư kinh tế - xã hội và 4 hình thức đầu tư theo pháp luật hiện hành.</p>\n                </div>\n              </div>\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] flex items-start gap-2.5\">\n                <span class=\"w-5 h-5 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                <div>\n                  <strong class=\"text-[#111827]\">Đặc điểm &amp; Chu kỳ dự án:</strong>\n                  <p class=\"text-[#666666] m-0 mt-0.5\">Nhận diện 5 đặc điểm cốt lõi của một dự án và 3 giai đoạn sống: Chuẩn bị đầu tư, Thực hiện đầu tư, Vận hành khai thác.</p>\n                </div>\n              </div>\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] flex items-start gap-2.5\">\n                <span class=\"w-5 h-5 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                <div>\n                  <strong class=\"text-[#111827]\">Dòng ngân lưu dự án (Cash Flow):</strong>\n                  <p class=\"text-[#666666] m-0 mt-0.5\">Xác định dòng tiền vào (Inflow), dòng tiền ra (Outflow) và các yếu tố ảnh hưởng trực tiếp đến tính khả thi tài chính.</p>\n                </div>\n              </div>\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] flex items-start gap-2.5\">\n                <span class=\"w-5 h-5 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">4</span>\n                <div>\n                  <strong class=\"text-[#111827]\">Khung Quản trị dự án:</strong>\n                  <p class=\"text-[#666666] m-0 mt-0.5\">Trình bày vai trò, mục tiêu \"Tam giác kiềm tỏa\" (Thời gian - Chi phí - Chất lượng) và tiến trình 5 giai đoạn quản trị.</p>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Section 1.1 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>1.1.</span> Bản Chất Của Đầu Tư Và Các Hình Thức Đầu Tư\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Theo nghĩa chung nhất, <strong>đầu tư</strong> là việc hy sinh các nguồn lực ở hiện tại (tiền vốn, thời gian, công sức, tài nguyên) với kỳ vọng thu về các kết quả có lợi trong tương lai. Kết quả này có thể là sự gia tăng về tài sản tài chính, năng lực sản xuất, lợi thế thương mại hoặc các giá trị văn hóa - xã hội.\n            </p>\n            <div class=\"border-l-4 border-[#8B1E2D] bg-[#FCEEEF]/50 p-4 rounded-r-xl my-3 text-xs sm:text-sm\">\n              <strong class=\"text-[#8B1E2D] font-bold block mb-1\">Khái niệm cốt lõi theo Luật Đầu tư Việt Nam:</strong>\n              <p class=\"m-0 leading-relaxed text-[#333333]\">\n                \"Đầu tư kinh doanh là việc nhà đầu tư bỏ vốn đầu tư để thực hiện hoạt động kinh doanh thông qua việc thành lập tổ chức kinh tế; đầu tư góp vốn, mua cổ phần, phần vốn góp của tổ chức kinh tế; đầu tư theo hình thức hợp đồng hoặc thực hiện dự án đầu tư.\"\n              </p>\n            </div>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Hoạt động đầu tư trong nền kinh tế thường được phân thành 4 hình thức chủ yếu:\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 my-3 text-xs\">\n              <div class=\"p-3 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">1. Thành lập tổ chức kinh tế mới:</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Nhà đầu tư trong nước hoặc nước ngoài thành lập doanh nghiệp mới (Công ty TNHH, Công ty Cổ phần, Doanh nghiệp tư nhân) để tiến hành hoạt động sản xuất kinh doanh.</p>\n              </div>\n              <div class=\"p-3 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">2. Đầu tư theo hình thức hợp đồng:</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Bao gồm Hợp đồng Hợp tác kinh doanh (BCC - không thành lập pháp nhân mới) và các Hợp đồng đối tác công tư PPP (BOT, BTO, BT, BOO).</p>\n              </div>\n              <div class=\"p-3 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">3. Đầu tư phát triển, mở rộng kinh doanh:</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Đầu tư chiều sâu, đổi mới công nghệ, mua sắm dây chuyền thiết bị hiện đại, mở rộng quy mô phân xưởng hoặc phát triển thêm chi nhánh mới.</p>\n              </div>\n              <div class=\"p-3 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">4. Góp vốn, mua cổ phần, M&amp;A:</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Mua lại cổ phần, sáp nhập hoặc thâu tóm doanh nghiệp nhằm nắm quyền chi phối, tái cơ cấu hoặc khai thác nhanh thị phần sẵn có.</p>\n              </div>\n            </div>\n          </div>\n\n          <!-- Section 1.2 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>1.2.</span> Dự Án Và Đặc Điểm Cốt Lõi Của Dự Án\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Theo Viện Quản trị Dự án Hoa Kỳ (PMI), <strong>Dự án (Project)</strong> là một nỗ lực tạm thời được thực hiện nhằm tạo ra một sản phẩm, dịch vụ hoặc kết quả duy nhất. Dự án khác biệt căn bản với các hoạt động vận hành thường nhật (Operations) thông qua 5 đặc điểm nổi bật sau:\n            </p>\n            <div class=\"table-container overflow-x-auto my-3\">\n              <table class=\"w-full border-collapse border border-[#E8E0E1] text-xs\">\n                <thead>\n                  <tr class=\"bg-[#8B1E2D] text-white\">\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-1/4\">Đặc điểm</th>\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-2/4\">Bản chất học thuật &amp; Nội dung</th>\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-1/4\">Ví dụ minh họa</th>\n                  </tr>\n                </thead>\n                <tbody class=\"divide-y divide-[#E8E0E1]\">\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">1. Tính mục đích rõ ràng</td>\n                    <td class=\"p-2.5 text-[#333333]\">Dự án luôn hướng đến việc đạt được những mục tiêu cụ thể đã được xác định trước về phạm vi, chi phí và thời gian.</td>\n                    <td class=\"p-2.5 text-[#666666]\">Xây dựng cầu đường dài 10km đúng thông số kỹ thuật.</td>\n                  </tr>\n                  <tr class=\"bg-[#FAF8F6]\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">2. Tính tạm thời (Thời hạn)</td>\n                    <td class=\"p-2.5 text-[#333333]\">Dự án luôn có thời điểm bắt đầu và thời điểm kết thúc rõ ràng. Khi các mục tiêu đã đạt được, dự án sẽ giải thể.</td>\n                    <td class=\"p-2.5 text-[#666666]\">Thời gian thi công từ 01/01/2024 đến 30/12/2025.</td>\n                  </tr>\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">3. Tính duy nhất / Độc đáo</td>\n                    <td class=\"p-2.5 text-[#333333]\">Sản phẩm hoặc dịch vụ tạo ra là duy nhất, không có sự lặp lại giống hệt 100% về điều kiện thi công, địa điểm hay nguồn lực.</td>\n                    <td class=\"p-2.5 text-[#666666]\">Phát triển ứng dụng Mobile App cho ngân hàng X.</td>\n                  </tr>\n                  <tr class=\"bg-[#FAF8F6]\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">4. Nguồn lực giới hạn</td>\n                    <td class=\"p-2.5 text-[#333333]\">Mọi dự án đều vận hành dưới sự ràng buộc nghiêm ngặt về ngân sách, nhân lực, thiết bị máy móc và nguyên vật liệu.</td>\n                    <td class=\"p-2.5 text-[#666666]\">Ngân sách tối đa 50 tỷ VNĐ, đội ngũ 25 kỹ sư.</td>\n                  </tr>\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">5. Tính không chắc chắn / Rủi ro</td>\n                    <td class=\"p-2.5 text-[#333333]\">Do hướng tới tương lai và tính độc đáo, dự án luôn tiềm ẩn mức độ rủi ro nhất định về kỹ thuật, tài chính và thị trường.</td>\n                    <td class=\"p-2.5 text-[#666666]\">Biến động giá sắt thép, thời tiết mưa bão kéo dài.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <!-- Section 1.3 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>1.3.</span> Chu Kỳ Sống Của Dự Án Đầu Tư (Project Life Cycle)\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Chu kỳ sống của một dự án đầu tư trải qua 3 giai đoạn kế tiếp nhau một cách chặt chẽ:\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-3 my-3 text-xs\">\n              <div class=\"p-3.5 bg-white rounded-xl border-t-4 border-[#8B1E2D] border-x border-b border-[#E8E0E1] shadow-2xs space-y-1.5\">\n                <span class=\"w-6 h-6 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center\">GĐ 1</span>\n                <h4 class=\"font-extrabold text-slate-900 text-xs sm:text-sm\">Chuẩn bị đầu tư</h4>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Nghiên cứu cơ hội đầu tư, lập Báo cáo nghiên cứu tiền khả thi (Pre-FS), Báo cáo khả thi (FS), thẩm định dự án và ra quyết định đầu tư.</p>\n              </div>\n              <div class=\"p-3.5 bg-white rounded-xl border-t-4 border-amber-500 border-x border-b border-[#E8E0E1] shadow-2xs space-y-1.5\">\n                <span class=\"w-6 h-6 rounded-md bg-amber-500 text-white font-bold text-xs flex items-center justify-center\">GĐ 2</span>\n                <h4 class=\"font-extrabold text-slate-900 text-xs sm:text-sm\">Thực hiện đầu tư</h4>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Đàm phán ký kết hợp đồng, thiết kế kỹ thuật, thi công xây lắp, mua sắm máy móc thiết bị, chạy thử nghiệm thu và đào tạo công nhân viên.</p>\n              </div>\n              <div class=\"p-3.5 bg-white rounded-xl border-t-4 border-emerald-600 border-x border-b border-[#E8E0E1] shadow-2xs space-y-1.5\">\n                <span class=\"w-6 h-6 rounded-md bg-emerald-600 text-white font-bold text-xs flex items-center justify-center\">GĐ 3</span>\n                <h4 class=\"font-extrabold text-slate-900 text-xs sm:text-sm\">Vận hành khai thác</h4>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Đưa công trình vào khai thác thương mại, tạo ra dòng tiền thu nhập hoàn vốn, thu hồi vốn lưu động, trả nợ vay và thanh lý tài sản khi hết hạn.</p>\n              </div>\n            </div>\n          </div>\n\n          <!-- Section 1.4 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>1.4.</span> Quản Trị Dự Án &amp; Tam Giác Kiềm Tỏa (Iron Triangle)\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              <strong>Quản trị dự án (Project Management)</strong> là quá trình áp dụng kiến thức, kỹ năng, công cụ và kỹ thuật vào các hoạt động của dự án nhằm đáp ứng hoặc vượt qua các yêu cầu và kỳ vọng của các bên liên quan.\n            </p>\n            <div class=\"border-l-4 border-amber-500 bg-amber-50/60 p-4 rounded-r-xl my-3 text-xs sm:text-sm\">\n              <strong class=\"text-amber-900 font-bold block mb-1\">Mục tiêu kiềm tỏa cốt lõi (Tam giác quản trị):</strong>\n              <p class=\"m-0 leading-relaxed text-[#333333]\">\n                Nhà quản trị dự án phải cân bằng 3 ràng buộc chính yếu: <strong>Thời gian (Time)</strong> — hoàn thành đúng tiến độ; <strong>Chi phí (Cost)</strong> — nằm trong giới hạn ngân sách được duyệt; và <strong>Chất lượng / Phạm vi (Quality &amp; Scope)</strong> — đáp ứng toàn bộ các thông số kỹ thuật tiêu chuẩn. Bất kỳ sự thay đổi nào ở một đỉnh của tam giác đều sẽ tác động trực tiếp đến hai đỉnh còn lại.\n              </p>\n            </div>\n          </div>\n\n          <!-- Chapter Summary -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt Trọng Tâm Chương 1\n            </h4>\n            <ul class=\"text-xs text-[#333333] space-y-1.5 pl-4 list-disc leading-relaxed\">\n              <li>Đầu tư là sự đánh đổi nguồn lực hiện tại để kỳ vọng kết quả vượt trội trong tương lai; có 4 hình thức đầu tư chính yếu theo luật định.</li>\n              <li>Dự án sở hữu 5 đặc trưng: Mục đích cụ thể, thời hạn xác định, tính duy nhất, nguồn lực hữu hạn và chứa đựng rủi ro.</li>\n              <li>Chu kỳ dự án gồm 3 giai đoạn: Chuẩn bị đầu tư (quyết định tính khả thi), Thực hiện đầu tư (tiêu tốn vốn lớn nhất) và Vận hành (tạo doanh thu).</li>\n              <li>Nhiệm vụ trọng tâm của Giám đốc dự án là tối ưu hóa \"Tam giác kiềm tỏa\" giữa Thời gian, Chi phí và Chất lượng công trình.</li>\n            </ul>\n          </div>\n\n          <!-- Glossary -->\n          <div class=\"border border-[#E8E0E1] rounded-2xl p-4 bg-white\">\n            <h4 class=\"text-xs font-bold text-slate-700 uppercase tracking-wider mb-2\">Thuật Ngữ Chuyên Ngành Anh — Việt (Chương 1)</h4>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs\">\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Project Life Cycle:</strong> Chu kỳ sống của dự án</div>\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Feasibility Study (FS):</strong> Nghiên cứu khả thi</div>\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Cash Flow:</strong> Dòng tiền / Ngân lưu</div>\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Iron Triangle:</strong> Tam giác kiềm tỏa (Thời gian, Chi phí, Chất lượng)</div>\n            </div>\n          </div>\n\n          <!-- Review Questions -->\n          <div class=\"bg-white border border-[#E8E0E1] rounded-2xl p-4 sm:p-5\">\n            <h4 class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider mb-2\">Câu Hỏi Ôn Tập Chương 1</h4>\n            <ol class=\"text-xs text-[#333333] space-y-2 pl-4 list-decimal leading-relaxed\">\n              <li>Trình bày khái niệm đầu tư và phân tích 4 hình thức đầu tư kinh doanh chủ yếu tại Việt Nam?</li>\n              <li>Phân tích 5 đặc điểm cốt lõi của một dự án? Cho ví dụ phân biệt giữa hoạt động của dự án và hoạt động vận hành thường nhật của doanh nghiệp?</li>\n              <li>Trình bày các giai đoạn trong chu kỳ sống của một dự án đầu tư? Giai đoạn nào có ý nghĩa quyết định nhất đến sự thành bại của dự án? Vì sao?</li>\n              <li>Phân tích mối quan hệ đánh đổi giữa Thời gian, Chi phí và Chất lượng trong quản trị dự án?</li>\n            </ol>\n          </div>\n\n          <!-- Chapter Navigation Bar -->\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <span class=\"text-slate-400\">← Bắt đầu giáo trình</span>\n            <a href=\"#chuong2\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 2: Lựa Chọn Dự Án →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 2: LỰA CHỌN DỰ ÁN                                                  -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong2\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] overflow-hidden text-[#333333] transition-all\">\n        <div class=\"p-4 sm:p-7 space-y-6\">\n\n          <!-- Chapter Header Banner -->\n          <div class=\"chapter-header-banner rounded-2xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] p-5 sm:p-7 text-white shadow-md relative overflow-hidden\">\n            <div class=\"relative z-10 flex flex-col gap-2\">\n              <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-400 text-slate-950 font-black text-xs uppercase tracking-wider w-fit\">\n                <span>CHƯƠNG 02</span>\n              </div>\n              <h2 class=\"text-xl sm:text-2xl md:text-3xl font-black tracking-tight uppercase leading-tight text-white m-0\">\n                Lựa Chọn Dự Án\n              </h2>\n              <p class=\"text-xs sm:text-sm leading-relaxed max-w-3xl m-0 font-medium text-[#FCEEEF]\">\n                Các phương pháp thẩm định tài chính dự án định lượng: Thời gian hoàn vốn (PP), Hiện giá ròng (NPV), Tỷ suất sinh lời nội bộ (IRR), Chỉ số sinh lời (PI) và các mô hình đánh giá định tính.\n              </p>\n            </div>\n          </div>\n\n          <!-- Chapter Objectives Card -->\n          <div class=\"bg-gradient-to-br from-white via-[#FCEEEF]/40 to-[#FAF8F6] rounded-2xl border border-[#E8E0E1] p-4 sm:p-5 shadow-2xs\">\n            <div class=\"flex items-center gap-2.5 mb-3 border-b border-[#E8E0E1] pb-2.5\">\n              <span class=\"w-7 h-7 rounded-lg bg-[#8B1E2D] text-white flex items-center justify-center text-sm font-bold\">🎯</span>\n              <div>\n                <h3 class=\"font-extrabold text-[#111827] text-xs sm:text-sm m-0 tracking-tight\">Mục Tiêu Trọng Tâm Chương 2</h3>\n                <p class=\"text-[11px] text-[#666666] m-0\">Chuẩn đầu ra kiến thức và kỹ năng sau khi hoàn thành chương:</p>\n              </div>\n            </div>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs\">\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] flex items-start gap-2.5\">\n                <span class=\"w-5 h-5 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                <div>\n                  <strong class=\"text-[#111827]\">Phương pháp PP &amp; DPP:</strong>\n                  <p class=\"text-[#666666] m-0 mt-0.5\">Xác định thời gian hoàn vốn giản đơn và hoàn vốn có chiết khấu, phân tích ưu nhược điểm.</p>\n                </div>\n              </div>\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] flex items-start gap-2.5\">\n                <span class=\"w-5 h-5 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                <div>\n                  <strong class=\"text-[#111827]\">Hiện giá thuần (NPV):</strong>\n                  <p class=\"text-[#666666] m-0 mt-0.5\">Thành thạo công thức tính NPV, hiểu rõ quy tắc chấp thuận dự án độc lập và dự án loại trừ lẫn nhau.</p>\n                </div>\n              </div>\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] flex items-start gap-2.5\">\n                <span class=\"w-5 h-5 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                <div>\n                  <strong class=\"text-[#111827]\">Suất sinh lời nội hoàn (IRR) &amp; PI:</strong>\n                  <p class=\"text-[#666666] m-0 mt-0.5\">Tính toán IRR bằng phương pháp nội suy, tính chỉ số sinh lời PI và xử lý mâu thuẫn giữa NPV và IRR.</p>\n                </div>\n              </div>\n              <div class=\"p-3 bg-white rounded-xl border border-[#E8E0E1] flex items-start gap-2.5\">\n                <span class=\"w-5 h-5 rounded-md bg-[#8B1E2D] text-white font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">4</span>\n                <div>\n                  <strong class=\"text-[#111827]\">Mô hình đánh giá định tính:</strong>\n                  <p class=\"text-[#666666] m-0 mt-0.5\">Vận dụng danh mục kiểm tra (Checklist) và Ma trận cho điểm có trọng số (Scoring Model).</p>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Section 2.1 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>2.1.</span> Tiêu Chí Đánh Giá Định Lượng Tài Chính Dự Án\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Đánh giá hiệu quả tài chính là bước trọng yếu nhất trong lựa chọn dự án. Có 4 chỉ tiêu định lượng kinh điển được áp dụng rộng rãi:\n            </p>\n\n            <!-- Formula PP -->\n            <div class=\"bg-[#FAF8F6] border border-[#E8E0E1] rounded-xl p-4 my-3 text-xs sm:text-sm\">\n              <strong class=\"text-[#8B1E2D] font-bold block mb-1\">1. Phương pháp Thời gian hoàn vốn (Payback Period - PP):</strong>\n              <p class=\"m-0 text-[#333333] leading-relaxed\">\n                Là khoảng thời gian cần thiết để tổng dòng tiền thu nhập của dự án bù đắp đủ số vốn đầu tư ban đầu ($C_0$).\n              </p>\n              <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1] my-2 text-center\">\n                <span class=\"font-mono font-bold text-[#8B1E2D]\">Trường hợp dòng tiền đều: PP = Vốn đầu tư ban đầu (C₀) / Dòng tiền thu hàng năm (CF)</span>\n              </div>\n              <p class=\"text-xs text-[#666666] m-0\">\n                <em>Nguyên tắc quyết định:</em> Chấp nhận dự án nếu $PP le PP_{chuẩn}$. Nhược điểm: Bỏ qua giá trị tiền tệ theo thời gian và không xét dòng tiền sau thời điểm hoàn vốn.\n              </p>\n            </div>\n\n            <!-- Formula NPV -->\n            <div class=\"bg-[#FAF8F6] border border-[#E8E0E1] rounded-xl p-4 my-3 text-xs sm:text-sm\">\n              <strong class=\"text-[#8B1E2D] font-bold block mb-1\">2. Phương pháp Hiện giá thuần (Net Present Value - NPV):</strong>\n              <p class=\"m-0 text-[#333333] leading-relaxed\">\n                Là chênh lệch giữa tổng giá trị hiện tại của các dòng tiền thu nhập trong tương lai và vốn đầu tư ban đầu, được chiết khấu theo chi phí vốn $r$:\n              </p>\n              <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1] my-2 text-center font-mono font-bold text-[#8B1E2D]\">\n                NPV = ∑ [ CFₜ / (1 + r)ᵗ ] − C₀ (với t chạy từ 1 đến n)\n              </div>\n              <ul class=\"text-xs text-[#333333] pl-4 list-disc space-y-1\">\n                <li><strong>NPV &gt; 0:</strong> Dự án sinh lời cao hơn chi phí sử dụng vốn, gia tăng giá trị cho doanh nghiệp → <em>Chấp thuận</em>.</li>\n                <li><strong>NPV = 0:</strong> Dự án vừa đủ bù đắp chi phí vốn → <em>Cân nhắc tùy mục tiêu chiến lược</em>.</li>\n                <li><strong>NPV &lt; 0:</strong> Dự án gây thua lỗ về mặt tài chính → <em>Bác bỏ</em>.</li>\n              </ul>\n            </div>\n\n            <!-- Formula IRR -->\n            <div class=\"bg-[#FAF8F6] border border-[#E8E0E1] rounded-xl p-4 my-3 text-xs sm:text-sm\">\n              <strong class=\"text-[#8B1E2D] font-bold block mb-1\">3. Phương pháp Suất sinh lời nội hoàn (Internal Rate of Return - IRR):</strong>\n              <p class=\"m-0 text-[#333333] leading-relaxed\">\n                Là mức lãi suất chiết khấu mà tại đó giá trị hiện tại của dòng thu nhập tương lai đúng bằng vốn đầu tư ban đầu, tức là làm cho <strong>NPV = 0</strong>.\n              </p>\n              <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1] my-2 text-center font-mono font-bold text-[#8B1E2D]\">\n                IRR = r₁ + [ NPV₁ / (NPV₁ + |NPV₂|) ] × (r₂ − r₁)\n              </div>\n              <p class=\"text-xs text-[#666666] m-0\">\n                <em>Nguyên tắc:</em> Chấp thuận dự án khi $IRR ge r$ (chi phí sử dụng vốn hoặc tỷ suất sinh lời kỳ vọng tối thiểu).\n              </p>\n            </div>\n\n            <!-- Formula PI -->\n            <div class=\"bg-[#FAF8F6] border border-[#E8E0E1] rounded-xl p-4 my-3 text-xs sm:text-sm\">\n              <strong class=\"text-[#8B1E2D] font-bold block mb-1\">4. Chỉ số sinh lời (Profitability Index - PI):</strong>\n              <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1] my-2 text-center font-mono font-bold text-[#8B1E2D]\">\n                PI = [ Giá trị hiện tại của các dòng tiền (PV of Inflows) ] / Vốn đầu tư ban đầu (C₀)\n              </div>\n              <p class=\"text-xs text-[#666666] m-0\">\n                <em>Nguyên tắc:</em> Chấp thuận khi $PI ge 1.0$. PI đặc biệt hiệu quả khi lựa chọn danh mục dự án trong bối cảnh ngân sách bị giới hạn (Rationing Capital).\n              </p>\n            </div>\n          </div>\n\n          <!-- Section 2.2 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>2.2.</span> Tiêu Chí Đánh Giá Định Tính Dự Án\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Bên cạnh các con số tài chính, dự án cần được xem xét dưới lăng kính chiến lược, môi trường và xã hội:\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 my-3 text-xs\">\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">1. Danh mục kiểm tra (Checklist Model):</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Liệt kê danh sách các câu hỏi then chốt về sự phù hợp chiến lược, rủi ro công nghệ, tính sẵn sàng của nguồn nhân lực và tuân thủ pháp lý môi trường để bỏ phiếu Yes/No.</p>\n              </div>\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">2. Ma trận cho điểm có trọng số (Weighted Scoring Model):</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Gán trọng số $w_i$ cho từng tiêu chí ($∑ w_i = 1.0$) và chấm điểm $s_i$ từ 1 đến 10. Điểm tổng hợp $S = ∑ (w_i × s_i)$. Dự án có tổng điểm cao nhất sẽ được ưu tiên.</p>\n              </div>\n            </div>\n          </div>\n\n          <!-- Chapter Summary -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt Trọng Tâm Chương 2\n            </h4>\n            <ul class=\"text-xs text-[#333333] space-y-1.5 pl-4 list-disc leading-relaxed\">\n              <li>NPV là tiêu chuẩn vàng trong thẩm định tài chính vì đo lường trực tiếp giá trị tài sản ròng gia tăng cho cổ đông.</li>\n              <li>IRR phản ánh tỷ suất sinh lời tự thân của dự án; khi có xung đột giữa NPV và IRR ở các dự án loại trừ lẫn nhau, NPV luôn được ưu tiên lựa chọn.</li>\n              <li>Chỉ số PI hữu ích trong xếp hạng ưu tiên dự án khi doanh nghiệp bị giới hạn ngân sách đầu tư.</li>\n              <li>Cần kết hợp hài hòa tiêu chí định lượng tài chính và tiêu chí định tính chiến lược để đảm bảo sự phát triển bền vững.</li>\n            </ul>\n          </div>\n\n          <!-- Glossary -->\n          <div class=\"border border-[#E8E0E1] rounded-2xl p-4 bg-white\">\n            <h4 class=\"text-xs font-bold text-slate-700 uppercase tracking-wider mb-2\">Thuật Ngữ Chuyên Ngành Anh — Việt (Chương 2)</h4>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs\">\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Net Present Value (NPV):</strong> Hiện giá thuần / ròng</div>\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Internal Rate of Return (IRR):</strong> Tỷ suất sinh lời nội bộ</div>\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Payback Period (PP):</strong> Thời gian hoàn vốn</div>\n              <div class=\"p-2 bg-[#FAF8F6] rounded-lg\"><strong>Profitability Index (PI):</strong> Chỉ số sinh lời</div>\n            </div>\n          </div>\n\n          <!-- Review Questions -->\n          <div class=\"bg-white border border-[#E8E0E1] rounded-2xl p-4 sm:p-5\">\n            <h4 class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider mb-2\">Câu Hỏi Ôn Tập Chương 2</h4>\n            <ol class=\"text-xs text-[#333333] space-y-2 pl-4 list-decimal leading-relaxed\">\n              <li>Trình bày khái niệm, công thức và quy tắc lựa chọn dự án theo phương pháp NPV? Vì sao NPV được xem là tiêu chuẩn tối ưu?</li>\n              <li>Nêu khái niệm và cách xác định IRR bằng phương pháp nội suy? Trong trường hợp nào việc ra quyết định theo IRR có thể dẫn đến sai lầm?</li>\n              <li>So sánh ưu điểm và hạn chế của phương pháp thời gian hoàn vốn giản đơn (PP)?</li>\n              <li>Dự án A có vốn đầu tư 100 triệu VNĐ, dòng tiền thu hồi 3 năm lần lượt là 40, 50, 60 triệu VNĐ. Với chi phí vốn 10%, hãy tính NPV của dự án?</li>\n            </ol>\n          </div>\n\n          <!-- Chapter Navigation Bar -->\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong1\" class=\"inline-flex items-center gap-1 text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 1: Tổng Quan\n            </a>\n            <a href=\"#chuong3\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 3: Tổ Chức Dự Án →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 3: TỔ CHỨC DỰ ÁN                                                   -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong3\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] overflow-hidden text-[#333333] transition-all\">\n        <div class=\"p-4 sm:p-7 space-y-6\">\n\n          <!-- Chapter Header Banner -->\n          <div class=\"chapter-header-banner rounded-2xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] p-5 sm:p-7 text-white shadow-md relative overflow-hidden\">\n            <div class=\"relative z-10 flex flex-col gap-2\">\n              <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-400 text-slate-950 font-black text-xs uppercase tracking-wider w-fit\">\n                <span>CHƯƠNG 03</span>\n              </div>\n              <h2 class=\"text-xl sm:text-2xl md:text-3xl font-black tracking-tight uppercase leading-tight text-white m-0\">\n                Tổ Chức Dự Án\n              </h2>\n              <p class=\"text-xs sm:text-sm leading-relaxed max-w-3xl m-0 font-medium text-[#FCEEEF]\">\n                Các mô hình cơ cấu tổ chức dự án (Chức năng, Chuyên trách dự án, Ma trận), vai trò của Giám đốc dự án (Project Manager) và kỹ năng xây dựng đội ngũ dự án hiệu suất cao.\n              </p>\n            </div>\n          </div>\n\n          <!-- Section 3.1 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>3.1.</span> Ba Mô Hình Cơ Cấu Tổ Chức Dự Án\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Việc lựa chọn mô hình tổ chức phù hợp quyết định trực tiếp đến quyền hạn của nhà quản trị dự án, tốc độ ra quyết định và mức độ sử dụng hiệu quả nguồn lực:\n            </p>\n\n            <div class=\"table-container overflow-x-auto my-3\">\n              <table class=\"w-full border-collapse border border-[#E8E0E1] text-xs\">\n                <thead>\n                  <tr class=\"bg-[#8B1E2D] text-white\">\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-1/4\">Mô hình tổ chức</th>\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-2/5\">Đặc điểm &amp; Quyền hạn Giám đốc DA</th>\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-1/3\">Ưu điểm &amp; Nhược điểm chính</th>\n                  </tr>\n                </thead>\n                <tbody class=\"divide-y divide-[#E8E0E1]\">\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">1. Mô hình Chức năng (Functional)</td>\n                    <td class=\"p-2.5 text-[#333333]\">Dự án được giao vào một phòng chức năng (Kỹ thuật, Kế toán, Marketing). Quyền hạn PM rất thấp, PM đóng vai trò điều phối viên.</td>\n                    <td class=\"p-2.5 text-[#666666]\"><strong>Ưu:</strong> Tận dụng chuyên môn sâu, nhân viên có chỗ dựa sau dự án.<br><strong>Nhược:</strong> Khách hàng không là trọng tâm, phối hợp liên phòng ban chậm trễ.</td>\n                  </tr>\n                  <tr class=\"bg-[#FAF8F6]\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">2. Chuyên trách Dự án (Projectized)</td>\n                    <td class=\"p-2.5 text-[#333333]\">Đội ngũ nhân sự được tách hoàn toàn khỏi phòng chức năng để làm việc toàn thời gian cho dự án. Quyền hạn PM gần như tuyệt đối.</td>\n                    <td class=\"p-2.5 text-[#666666]\"><strong>Ưu:</strong> Giao tiếp nhanh, tập trung 100% mục tiêu dự án.<br><strong>Nhược:</strong> Lãng phí trùng lặp nguồn lực, nhân viên lo lắng mất việc khi DA kết thúc.</td>\n                  </tr>\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">3. Mô hình Ma trận (Matrix)</td>\n                    <td class=\"p-2.5 text-[#333333]\">Kết hợp giữa chức năng và dự án. Nhân sự chịu sự chỉ đạo kép (Dual Command): Trưởng phòng chức năng và Giám đốc dự án.</td>\n                    <td class=\"p-2.5 text-[#666666]\"><strong>Ưu:</strong> Tối ưu hóa nguồn lực, linh hoạt cao.<br><strong>Nhược:</strong> Xung đột quyền lực (Conflict of authority), căng thẳng tâm lý nhân sự.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <!-- Section 3.2 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>3.2.</span> Đội Ngũ Dự Án &amp; Vai Trò Của Giám Đốc Dự Án (PM)\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Giám đốc dự án đóng vai trò \"nhạc trưởng\", kết nối giữa khách hàng, ban giám đốc và các thành viên. Bốn giai đoạn phát triển nhóm dự án theo mô hình Tuckman:\n            </p>\n            <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs my-3\">\n              <div class=\"p-3 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1]\">\n                <strong class=\"text-[#8B1E2D] block\">1. Hình thành (Forming)</strong>\n                <span class=\"text-2xs text-[#666666]\">Làm quen, thăm dò vai trò và mục tiêu dự án.</span>\n              </div>\n              <div class=\"p-3 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1]\">\n                <strong class=\"text-[#8B1E2D] block\">2. Sóng gió (Storming)</strong>\n                <span class=\"text-2xs text-[#666666]\">Xung đột ý kiến, tranh giành ảnh hưởng và phương pháp.</span>\n              </div>\n              <div class=\"p-3 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1]\">\n                <strong class=\"text-[#8B1E2D] block\">3. Ổn định (Norming)</strong>\n                <span class=\"text-2xs text-[#666666]\">Thiết lập quy chuẩn, gắn kết và hợp tác tích cực.</span>\n              </div>\n              <div class=\"p-3 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1]\">\n                <strong class=\"text-[#8B1E2D] block\">4. Thể hiện (Performing)</strong>\n                <span class=\"text-2xs text-[#666666]\">Hiệu suất tối đa, tự chủ và tập trung hoàn thành mục tiêu.</span>\n              </div>\n            </div>\n          </div>\n\n          <!-- Summary & Questions -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt &amp; Câu Hỏi Ôn Tập Chương 3\n            </h4>\n            <p class=\"text-xs text-[#333333] leading-relaxed\">\n              <strong>Tóm tắt:</strong> Mô hình ma trận là mô hình hiện đại cân bằng giữa tính chuyên môn sâu và sự tập trung dự án, nhưng đòi hỏi kỹ năng giải quyết xung đột vượt trội của PM.\n            </p>\n            <ol class=\"text-xs text-[#333333] space-y-1 pl-4 list-decimal mt-2\">\n              <li>So sánh ưu nhược điểm của 3 mô hình tổ chức dự án? Khi nào nên áp dụng mô hình ma trận?</li>\n              <li>Trình bày 4 giai đoạn phát triển nhóm theo Tuckman và vai trò lãnh đạo tương ứng của PM?</li>\n            </ol>\n          </div>\n\n          <!-- Chapter Navigation Bar -->\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong2\" class=\"inline-flex items-center gap-1 text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 2: Lựa Chọn Dự Án\n            </a>\n            <a href=\"#chuong4\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 4: Kế Hoạch &amp; Ngân Sách →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 4: LẬP KẾ HOẠCH VÀ NGÂN SÁCH DỰ ÁN                                 -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong4\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] overflow-hidden text-[#333333] transition-all\">\n        <div class=\"p-4 sm:p-7 space-y-6\">\n\n          <!-- Chapter Header Banner -->\n          <div class=\"chapter-header-banner rounded-2xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] p-5 sm:p-7 text-white shadow-md relative overflow-hidden\">\n            <div class=\"relative z-10 flex flex-col gap-2\">\n              <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-400 text-slate-950 font-black text-xs uppercase tracking-wider w-fit\">\n                <span>CHƯƠNG 04</span>\n              </div>\n              <h2 class=\"text-xl sm:text-2xl md:text-3xl font-black tracking-tight uppercase leading-tight text-white m-0\">\n                Lập Kế Hoạch Và Ngân Sách Dự Án\n              </h2>\n              <p class=\"text-xs sm:text-sm leading-relaxed max-w-3xl m-0 font-medium text-[#FCEEEF]\">\n                Cơ cấu phân chia công việc (Work Breakdown Structure - WBS), gói công việc (Work Package), kỹ thuật ước lượng chi phí Bottom-up / Top-down và phương pháp thiết lập ngân sách dự án.\n              </p>\n            </div>\n          </div>\n\n          <!-- Section 4.1 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>4.1.</span> Cấu Trúc Phân Chia Công Việc (WBS)\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              <strong>WBS (Work Breakdown Structure)</strong> là sự phân rã có thứ bậc toàn bộ phạm vi công việc cần thực hiện thành các thành phần nhỏ hơn, dễ quản lý hơn. Đơn vị cơ sở nhỏ nhất ở đáy của WBS là <strong>Gói công việc (Work Package)</strong>.\n            </p>\n            <div class=\"border-l-4 border-[#8B1E2D] bg-[#FCEEEF]/50 p-4 rounded-r-xl my-3 text-xs sm:text-sm\">\n              <strong class=\"text-[#8B1E2D] font-bold block mb-1\">Quy tắc 100% trong xây dựng WBS:</strong>\n              <p class=\"m-0 leading-relaxed text-[#333333]\">\n                WBS phải bao gồm chính xác 100% công việc được định nghĩa trong phạm vi dự án và tạo ra toàn bộ sản phẩm chuyển giao (Deliverables). Không bỏ sót bất kỳ hạng mục nào và không đưa vào những công việc ngoài phạm vi dự án.\n              </p>\n            </div>\n          </div>\n\n          <!-- Section 4.2 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>4.2.</span> Ước Lượng Chi Phí &amp; Thiết Lập Ngân Sách Dự Án\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Có hai phương pháp tiếp cận chủ yếu trong lập ngân sách dự án:\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 my-3 text-xs\">\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">1. Ước lượng từ trên xuống (Top-down Budgeting):</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Ban lãnh đạo áp đặt hạn mức ngân sách tổng thể dựa trên kinh nghiệm từ các dự án tương tự trước đây, sau đó phân bổ nhỏ dần xuống các bộ phận. Nhanh nhưng dễ thiếu chính xác.</p>\n              </div>\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">2. Ước lượng từ dưới lên (Bottom-up Budgeting):</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Ước tính chi phí chi tiết cho từng gói công việc (Work Package) ở đáy WBS về nhân công, vật tư, máy móc rồi cộng dồn lên. Độ chính xác rất cao nhưng mất nhiều thời gian.</p>\n              </div>\n            </div>\n          </div>\n\n          <!-- Summary & Navigation -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt &amp; Câu Hỏi Ôn Tập Chương 4\n            </h4>\n            <p class=\"text-xs text-[#333333] leading-relaxed\">\n              <strong>Tóm tắt:</strong> WBS là xương sống của toàn bộ công tác lập kế hoạch, kiểm soát tiến độ và chi phí dự án. Ngân sách dự án phải tính đủ chi phí trực tiếp, gián tiếp và quỹ dự phòng rủi ro.\n            </p>\n            <ol class=\"text-xs text-[#333333] space-y-1 pl-4 list-decimal mt-2\">\n              <li>Trình bày quy tắc 100% trong xây dựng WBS và ý nghĩa của Work Package?</li>\n              <li>So sánh ưu nhược điểm của phương pháp ước lượng chi phí Top-down và Bottom-up?</li>\n            </ol>\n          </div>\n\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong3\" class=\"inline-flex items-center gap-1 text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 3: Tổ Chức Dự Án\n            </a>\n            <a href=\"#chuong5\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 5: Lập Tiến Độ →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 5: LẬP TIẾN ĐỘ DỰ ÁN                                                -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong5\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] overflow-hidden text-[#333333] transition-all\">\n        <div class=\"p-4 sm:p-7 space-y-6\">\n\n          <!-- Chapter Header Banner -->\n          <div class=\"chapter-header-banner rounded-2xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] p-5 sm:p-7 text-white shadow-md relative overflow-hidden\">\n            <div class=\"relative z-10 flex flex-col gap-2\">\n              <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-400 text-slate-950 font-black text-xs uppercase tracking-wider w-fit\">\n                <span>CHƯƠNG 05</span>\n              </div>\n              <h2 class=\"text-xl sm:text-2xl md:text-3xl font-black tracking-tight uppercase leading-tight text-white m-0\">\n                Lập Tiến Độ Dự Án\n              </h2>\n              <p class=\"text-xs sm:text-sm leading-relaxed max-w-3xl m-0 font-medium text-[#FCEEEF]\">\n                Sơ đồ Gantt, sơ đồ mạng AOA/AON, phương pháp đường găng (Critical Path Method - CPM), kỹ thuật ước tính 3 mốc thời gian (PERT) và tính toán thời gian dự trữ (Float / Slack).\n              </p>\n            </div>\n          </div>\n\n          <!-- Section 5.1 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>5.1.</span> Biểu Đồ Gantt Và Sơ Đồ Mạng\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              <strong>Biểu đồ Gantt</strong> là công cụ trực quan biểu diễn các công việc dưới dạng thanh ngang trên trục thời gian. Ưu điểm là dễ hiểu, nhưng nhược điểm lớn là không thể hiện rõ mối quan hệ phụ thuộc logic giữa các công việc phức tạp.\n            </p>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              <strong>Sơ đồ mạng (Network Diagram)</strong> khắc phục hạn chế trên bằng cách mô tả chuỗi công việc logic qua hai dạng:\n            </p>\n            <ul class=\"text-xs text-[#333333] pl-4 list-disc space-y-1\">\n              <li><strong>AOA (Activity-on-Arrow):</strong> Công việc nằm trên mũi tên, nút biểu thị sự kiện bắt đầu/kết thúc.</li>\n              <li><strong>AON (Activity-on-Node):</strong> Công việc nằm trong nút hộp, mũi tên biểu thị mối quan hệ phụ thuộc trước sau.</li>\n            </ul>\n          </div>\n\n          <!-- Section 5.2 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>5.2.</span> Phương Pháp Đường Găng (CPM) &amp; Kỹ Thuật PERT\n            </h3>\n            <div class=\"border-l-4 border-[#8B1E2D] bg-[#FCEEEF]/50 p-4 rounded-r-xl my-3 text-xs sm:text-sm\">\n              <strong class=\"text-[#8B1E2D] font-bold block mb-1\">Đường găng (Critical Path):</strong>\n              <p class=\"m-0 leading-relaxed text-[#333333]\">\n                Là chuỗi các công việc dài nhất nối từ sự kiện bắt đầu đến kết thúc dự án. Các công việc trên đường găng có <strong>thời gian dự trữ bằng 0 (Float = 0)</strong>. Bất kỳ sự chậm trễ nào của công việc găng đều làm chậm trễ tiến độ toàn bộ dự án.\n              </p>\n            </div>\n            <div class=\"bg-[#FAF8F6] border border-[#E8E0E1] rounded-xl p-4 my-3 text-xs sm:text-sm\">\n              <strong class=\"text-[#8B1E2D] font-bold block mb-1\">Công thức ước tính thời gian kỳ vọng trong PERT:</strong>\n              <p class=\"text-xs text-[#666666] mb-2\">Sử dụng 3 ước lượng thời gian: $a$ (lạc quan), $m$ (khả dĩ nhất), $b$ (bi quan):</p>\n              <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1] text-center font-mono font-bold text-[#8B1E2D]\">\n                Thời gian kỳ vọng: Tₑ = (a + 4m + b) / 6 &nbsp;|&nbsp; Phương sai: σ² = [ (b − a) / 6 ]²\n              </div>\n            </div>\n          </div>\n\n          <!-- Summary & Navigation -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt &amp; Câu Hỏi Ôn Tập Chương 5\n            </h4>\n            <p class=\"text-xs text-[#333333] leading-relaxed\">\n              <strong>Tóm tắt:</strong> Xác định đường găng và quản trị thời gian dự trữ là kỹ năng sống còn giúp PM phân bổ sự tập trung cao nhất vào các công việc then chốt.\n            </p>\n            <ol class=\"text-xs text-[#333333] space-y-1 pl-4 list-decimal mt-2\">\n              <li>Đường găng là gì? Ý nghĩa của việc xác định đường găng trong giám sát tiến độ?</li>\n              <li>Viết công thức tính thời gian kỳ vọng $T_e$ và độ lệch chuẩn $sigma$ trong phương pháp PERT?</li>\n            </ol>\n          </div>\n\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong4\" class=\"inline-flex items-center gap-1 text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 4: Kế Hoạch &amp; Ngân Sách\n            </a>\n            <a href=\"#chuong6\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 6: Phân Bổ Nguồn Lực →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 6: PHÂN BỔ NGUỒN LỰC                                               -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong6\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] overflow-hidden text-[#333333] transition-all\">\n        <div class=\"p-4 sm:p-7 space-y-6\">\n\n          <!-- Chapter Header Banner -->\n          <div class=\"chapter-header-banner rounded-2xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] p-5 sm:p-7 text-white shadow-md relative overflow-hidden\">\n            <div class=\"relative z-10 flex flex-col gap-2\">\n              <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-400 text-slate-950 font-black text-xs uppercase tracking-wider w-fit\">\n                <span>CHƯƠNG 06</span>\n              </div>\n              <h2 class=\"text-xl sm:text-2xl md:text-3xl font-black tracking-tight uppercase leading-tight text-white m-0\">\n                Phân Bổ Nguồn Lực\n              </h2>\n              <p class=\"text-xs sm:text-sm leading-relaxed max-w-3xl m-0 font-medium text-[#FCEEEF]\">\n                Phân loại nguồn lực dự án, kỹ thuật san bằng tài nguyên (Resource Leveling), giải quyết tắc nghẽn tài nguyên và tối ưu hóa sự đánh đổi Thời gian - Chi phí (Time-Cost Trade-off).\n              </p>\n            </div>\n          </div>\n\n          <!-- Section 6.1 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>6.1.</span> San Bằng Tài Nguyên (Resource Leveling)\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Trong thực tế, nhu cầu sử dụng nhân lực và máy móc thường biến động thất thường, lúc thiếu hụt gay gắt, lúc dư thừa lãng phí. <strong>San bằng tài nguyên</strong> là kỹ thuật dịch chuyển thời gian thực hiện của các công việc không găng (sử dụng thời gian dự trữ Float) để làm phẳng biểu đồ phụ tải nguồn lực, tránh hiện tượng quá tải đột ngột.\n            </p>\n          </div>\n\n          <!-- Section 6.2 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>6.2.</span> Đánh Đổi Thời Gian — Chi Phí (Crashing Project)\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Khi bắt buộc phải đẩy nhanh tiến độ dự án, PM phải tiến hành \"ép tiến độ\" (Crashing). Chi phí ép tiến độ trên một đơn vị thời gian được tính theo công thức:\n            </p>\n            <div class=\"p-3 bg-[#FAF8F6] rounded-lg border border-[#E8E0E1] text-center font-mono font-bold text-[#8B1E2D] text-xs sm:text-sm my-2\">\n              Chi phí ép trên một ngày = (Chi phí ép tiến độ − Chi phí bình thường) / (Thời gian bình thường − Thời gian ép)\n            </div>\n            <p class=\"text-xs text-[#666666] m-0\">\n              <em>Nguyên tắc:</em> Chỉ ép tiến độ các công việc nằm trên đường găng và ưu tiên công việc có chi phí ép trên mỗi đơn vị thời gian thấp nhất.\n            </p>\n          </div>\n\n          <!-- Summary & Navigation -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt &amp; Câu Hỏi Ôn Tập Chương 6\n            </h4>\n            <p class=\"text-xs text-[#333333] leading-relaxed\">\n              <strong>Tóm tắt:</strong> San bằng tài nguyên giúp doanh nghiệp ổn định nhân sự, tiết kiệm chi phí tuyển dụng sa thải thời vụ và nâng cao năng suất thi công.\n            </p>\n            <ol class=\"text-xs text-[#333333] space-y-1 pl-4 list-decimal mt-2\">\n              <li>Mục đích và nguyên lý của kỹ thuật san bằng tài nguyên (Resource Leveling)?</li>\n              <li>Nêu quy tắc lựa chọn công việc để rút ngắn thời gian dự án với chi phí tăng thêm tối thiểu?</li>\n            </ol>\n          </div>\n\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong5\" class=\"inline-flex items-center gap-1 text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 5: Lập Tiến Độ\n            </a>\n            <a href=\"#chuong7\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 7: Kiểm Soát Dự Án →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 7: KIỂM SOÁT DỰ ÁN                                                 -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong7\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] overflow-hidden text-[#333333] transition-all\">\n        <div class=\"p-4 sm:p-7 space-y-6\">\n\n          <!-- Chapter Header Banner -->\n          <div class=\"chapter-header-banner rounded-2xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] p-5 sm:p-7 text-white shadow-md relative overflow-hidden\">\n            <div class=\"relative z-10 flex flex-col gap-2\">\n              <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-400 text-slate-950 font-black text-xs uppercase tracking-wider w-fit\">\n                <span>CHƯƠNG 07</span>\n              </div>\n              <h2 class=\"text-xl sm:text-2xl md:text-3xl font-black tracking-tight uppercase leading-tight text-white m-0\">\n                Kiểm Soát Dự Án &amp; Phân Tích EVM\n              </h2>\n              <p class=\"text-xs sm:text-sm leading-relaxed max-w-3xl m-0 font-medium text-[#FCEEEF]\">\n                Tiến trình kiểm soát dự án, hệ thống quản lý giá trị thu được (Earned Value Management - EVM), các chỉ số biến sai CV, SV và các chỉ số hiệu năng CPI, SPI.\n              </p>\n            </div>\n          </div>\n\n          <!-- Section 7.1 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>7.1.</span> Phương Pháp Phân Tích Giá Trị Thu Được (EVM)\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              <strong>EVM (Earned Value Management)</strong> là phương pháp đo lường hiệu quả tổng hợp tiến độ và chi phí bằng cách tích hợp cả 3 yếu tố: Khối lượng công việc theo kế hoạch, Giá trị công việc thực tế đã hoàn thành và Chi phí thực tế đã chi ra.\n            </p>\n\n            <div class=\"table-container overflow-x-auto my-3\">\n              <table class=\"w-full border-collapse border border-[#E8E0E1] text-xs\">\n                <thead>\n                  <tr class=\"bg-[#8B1E2D] text-white\">\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-1/4\">Chỉ số EVM</th>\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-1/3\">Công thức tính</th>\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-5/12\">Ý nghĩa quản trị</th>\n                  </tr>\n                </thead>\n                <tbody class=\"divide-y divide-[#E8E0E1]\">\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">PV (Planned Value)</td>\n                    <td class=\"p-2.5 font-mono\">PV = % Kế hoạch × Ngân sách BAC</td>\n                    <td class=\"p-2.5 text-[#333333]\">Giá trị kế hoạch của công việc dự kiến hoàn thành tại thời điểm xét.</td>\n                  </tr>\n                  <tr class=\"bg-[#FAF8F6]\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">EV (Earned Value)</td>\n                    <td class=\"p-2.5 font-mono\">EV = % Thực tế × Ngân sách BAC</td>\n                    <td class=\"p-2.5 text-[#333333]\">Giá trị thu được từ khối lượng công việc thực tế đã hoàn thành.</td>\n                  </tr>\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">AC (Actual Cost)</td>\n                    <td class=\"p-2.5 font-mono\">AC = Chi phí thực tế sổ sách</td>\n                    <td class=\"p-2.5 text-[#333333]\">Tổng chi phí thực tế đã chi ra để đạt được giá trị EV.</td>\n                  </tr>\n                  <tr class=\"bg-[#FAF8F6]\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">Biến sai chi phí (CV)</td>\n                    <td class=\"p-2.5 font-mono\">CV = EV − AC</td>\n                    <td class=\"p-2.5 text-[#333333]\">CV &gt; 0: Tiết kiệm chi phí; CV &lt; 0: Bị vượt ngân sách.</td>\n                  </tr>\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">Biến sai tiến độ (SV)</td>\n                    <td class=\"p-2.5 font-mono\">SV = EV − PV</td>\n                    <td class=\"p-2.5 text-[#333333]\">SV &gt; 0: Nhanh hơn tiến độ; SV &lt; 0: Chậm tiến độ kế hoạch.</td>\n                  </tr>\n                  <tr class=\"bg-[#FAF8F6]\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">Chỉ số chi phí (CPI)</td>\n                    <td class=\"p-2.5 font-mono\">CPI = EV / AC</td>\n                    <td class=\"p-2.5 text-[#333333]\">CPI &gt; 1: Đạt hiệu quả chi phí cao; CPI &lt; 1: Bội chi.</td>\n                  </tr>\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">Chỉ số tiến độ (SPI)</td>\n                    <td class=\"p-2.5 font-mono\">SPI = EV / PV</td>\n                    <td class=\"p-2.5 text-[#333333]\">SPI &gt; 1: Tiến độ thực tế vượt mức kế hoạch; SPI &lt; 1: Bị chậm trễ.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <!-- Summary & Navigation -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt &amp; Câu Hỏi Ôn Tập Chương 7\n            </h4>\n            <p class=\"text-xs text-[#333333] leading-relaxed\">\n              <strong>Tóm tắt:</strong> Phương pháp EVM cung cấp bức tranh cảnh báo sớm chính xác nhất về sức khỏe tài chính và tiến độ của dự án, giúp ban quản lý đưa ra hành động khắc phục kịp thời.\n            </p>\n            <ol class=\"text-xs text-[#333333] space-y-1 pl-4 list-decimal mt-2\">\n              <li>Trình bày bản chất của 3 đại lượng PV, EV, AC trong phân tích giá trị thu được (EVM)?</li>\n              <li>Giả sử dự án có $PV = 200$ triệu, $EV = 180$ triệu, $AC = 190$ triệu. Hãy tính và nhận xét về CV, SV, CPI, SPI?</li>\n            </ol>\n          </div>\n\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong6\" class=\"inline-flex items-center gap-1 text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 6: Phân Bổ Nguồn Lực\n            </a>\n            <a href=\"#chuong8\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 8: Đánh Giá &amp; Kết Thúc →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 8: ĐÁNH GIÁ VÀ KẾT THÚC DỰ ÁN                                       -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong8\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] overflow-hidden text-[#333333] transition-all\">\n        <div class=\"p-4 sm:p-7 space-y-6\">\n\n          <!-- Chapter Header Banner -->\n          <div class=\"chapter-header-banner rounded-2xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] p-5 sm:p-7 text-white shadow-md relative overflow-hidden\">\n            <div class=\"relative z-10 flex flex-col gap-2\">\n              <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-400 text-slate-950 font-black text-xs uppercase tracking-wider w-fit\">\n                <span>CHƯƠNG 08</span>\n              </div>\n              <h2 class=\"text-xl sm:text-2xl md:text-3xl font-black tracking-tight uppercase leading-tight text-white m-0\">\n                Đánh Giá Và Kết Thúc Dự Án\n              </h2>\n              <p class=\"text-xs sm:text-sm leading-relaxed max-w-3xl m-0 font-medium text-[#FCEEEF]\">\n                Đánh giá và kiểm toán dự án (Project Audit), 4 hình thức kết thúc dự án, quy trình bàn giao nghiệm thu tài chính - kỹ thuật và bài học kinh nghiệm (Lessons Learned).\n              </p>\n            </div>\n          </div>\n\n          <!-- Section 8.1 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>8.1.</span> Đánh Giá Dự Án &amp; 4 Hình Thức Kết Thúc Dự Án\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Mọi dự án dù thành công rực rỡ hay bị dừng sớm đều phải trải qua giai đoạn kết thúc có kiểm soát:\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 my-3 text-xs\">\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">1. Kết thúc bằng Tuyệt chủng (Extinction):</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Dự án dừng lại hoàn toàn do đã hoàn thành tất cả các mục tiêu, hoặc bị hủy bỏ sớm do không còn tính khả thi.</p>\n              </div>\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">2. Kết thúc bằng Bổ sung / Tích hợp (Addition):</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Dự án chuyển hóa thành một bộ phận hoặc phòng ban chức năng chính thức trong cơ cấu tổ chức của doanh nghiệp.</p>\n              </div>\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">3. Kết thúc bằng Sáp nhập (Integration):</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Tài sản, con người và kết quả dự án được phân phối lại và hòa nhập vào các bộ phận vận hành sẵn có.</p>\n              </div>\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">4. Kết thúc bằng Cắt giảm ngân sách (Starvation):</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Dự án không bị tuyên bố khai tử chính thức nhưng bị cắt giảm dần ngân sách cho đến khi tự đình chỉ hoạt động.</p>\n              </div>\n            </div>\n          </div>\n\n          <!-- Section 8.2 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>8.2.</span> Báo Cáo Tổng Kết &amp; Bài Học Kinh Nghiệm (Lessons Learned)\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Báo cáo tổng kết dự án là văn bản chính thức ghi nhận toàn bộ kết quả thực hiện, đối chiếu giữa kế hoạch ban đầu và thực tế, quyết toán hợp đồng tài chính, bàn giao công trình và đúc rút bài học kinh nghiệm cho các dự án tiếp theo trong tương lai.\n            </p>\n          </div>\n\n          <!-- Summary & Questions -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt &amp; Câu Hỏi Ôn Tập Chương 8\n            </h4>\n            <p class=\"text-xs text-[#333333] leading-relaxed\">\n              <strong>Tóm tắt:</strong> Quy trình kết thúc chuẩn xác giúp giải phóng các nguồn lực an toàn, bảo vệ quyền lợi pháp lý của doanh nghiệp và lưu giữ tri thức quản trị vô giá.\n            </p>\n            <ol class=\"text-xs text-[#333333] space-y-1 pl-4 list-decimal mt-2\">\n              <li>Trình bày 4 hình thức kết thúc dự án và điều kiện xảy ra của từng hình thức?</li>\n              <li>Nội dung chủ yếu của một báo cáo tổng kết kết thúc dự án?</li>\n            </ol>\n          </div>\n\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong7\" class=\"inline-flex items-center gap-1 text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 7: Kiểm Soát Dự Án\n            </a>\n            <a href=\"#tailieuthamkhao\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Tài Liệu Tham Khảo ↓\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- TÀI LIỆU THAM KHẢO CHÍNH THỨC -->\n      <section id=\"tailieuthamkhao\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] p-5 sm:p-7 space-y-3\">\n        <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-2 flex items-center gap-2\">\n          <span>📚</span> Tài Liệu Tham Khảo Chính Thức Môn Học\n        </h3>\n        <ol class=\"text-xs text-[#333333] space-y-2 pl-4 list-decimal leading-relaxed\">\n          <li><strong>Nguyễn Thị Trúc Phương (Chủ biên) (2021)</strong>, <em>Giáo trình Quản trị dự án</em>, Trường Cao đẳng Kinh tế Thành phố Hồ Chí Minh (HCE).</li>\n          <li><strong>Project Management Institute - PMI (2021)</strong>, <em>A Guide to the Project Management Body of Knowledge (PMBOK Guide)</em>, 7th Edition.</li>\n          <li><strong>Trần Ngọc Thơ (2018)</strong>, <em>Quản trị tài chính doanh nghiệp</em>, NXB Tài Chính.</li>\n          <li><strong>Jack R. Meredith, Samuel J. Mantel Jr. (2017)</strong>, <em>Project Management: A Managerial Approach</em>, John Wiley &amp; Sons.</li>\n          <li><strong>Kerzner, H. (2017)</strong>, <em>Project Management: A Systems Approach to Planning, Scheduling, and Controlling</em>, Wiley.</li>\n        </ol>\n      </section>\n\n      <!-- KHUNG XÁC NHẬN IN ẤN VÀ XUẤT HỌC LIỆU A4 -->\n      <div class=\"no-print mt-10 p-6 sm:p-8 rounded-3xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] text-white shadow-md text-center space-y-3\">\n        <div class=\"flex items-center justify-center gap-2\">\n          <span class=\"text-xl\">📚</span>\n          <h3 class=\"text-base sm:text-lg font-bold text-white m-0\">In Ấn Và Xuất Học Liệu Giáo Trình Khổ A4</h3>\n        </div>\n        <p class=\"text-xs sm:text-sm text-[#FCEEEF] max-w-xl mx-auto m-0 leading-relaxed\">\n          Tài liệu chuẩn hóa phục vụ sinh viên ôn tập, nghiên cứu và in ấn theo tiêu chuẩn giáo trình chính quy khổ giấy A4 của Trường Cao đẳng Kinh tế TP.HCM.\n        </p>\n        <div class=\"pt-2 flex flex-wrap items-center justify-center gap-3\">\n          <button type=\"button\" onclick=\"window.print()\" class=\"bg-amber-400 hover:bg-amber-300 text-slate-950 font-bold px-5 py-2.5 rounded-xl text-xs sm:text-sm shadow-md transition-all flex items-center gap-2 cursor-pointer hover:scale-[1.02] active:scale-[0.98]\">\n            <span class=\"text-base\">🖨️</span> In Giáo Trình Toàn Tập\n          </button>\n          <button type=\"button\" onclick=\"window.print()\" class=\"bg-white hover:bg-[#FCEEEF] text-[#8B1E2D] font-bold px-5 py-2.5 rounded-xl text-xs sm:text-sm shadow-md transition-all flex items-center gap-2 cursor-pointer hover:scale-[1.02] active:scale-[0.98]\">\n            <span class=\"text-base\">📄</span> Xuất PDF Khổ Giấy A4\n          </button>\n        </div>\n      </div>\n\n    </div> <!-- /max-w-5xl -->\n\n    <!-- FLOATING ACTION BAR BÁM ĐÁY MÀN HÌNH -->\n    <div id=\"academicFloatingBar\" class=\"no-print fixed left-0 right-0 bottom-0 z-40 bg-white/95 backdrop-blur-md border-t border-[#E8E0E1] py-2 px-3 shadow-lg transition-transform duration-300\">\n      <div class=\"max-w-5xl mx-auto flex items-center justify-between gap-2\">\n        <div class=\"flex items-center gap-2 min-w-0\">\n          <span class=\"w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse shrink-0\"></span>\n          <span id=\"activeChapterName\" class=\"text-xs sm:text-sm font-bold text-slate-800 truncate\">\n            Đang xem: Chương 1 — Tổng Quan Quản Trị Dự Án\n          </span>\n        </div>\n        <div class=\"flex items-center gap-1.5 shrink-0\">\n          <a href=\"#chuong1\" class=\"p-2 sm:px-2.5 sm:py-1.5 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-bold transition-colors\" title=\"Mục lục\">\n            ☰ Mục Lục\n          </a>\n          <button type=\"button\" id=\"btnBackToTop\" onclick=\"window.scrollTo({top: 0, behavior: 'smooth'})\" class=\"p-2 sm:px-2.5 sm:py-1.5 rounded-lg bg-[#8B1E2D] hover:bg-[#C62828] text-white text-xs font-bold transition-colors cursor-pointer\" title=\"Về đầu trang\">\n            ▲ Lên Đầu\n          </button>\n        </div>\n      </div>\n    </div>\n\n  </div> <!-- /tkd-page-scope -->\n";
